\label{gi}
Let $G$ be a group and let $H,K,L$ be subgroups of $G$, with $H\subseteq K$. Then:
\begin{itemize}
\item[(a)] $[G:H]=[G:K][K:H]$;
\item[(b)] $[LH:H]=[L:H\cap L]$;
\item[(c)] $[K:H]\geq[K\cap L:H\cap L]$.
\end{itemize}
If $N$ is a normal subgroup of $G$, $q:G\to G/N$ is the canonical projection and $N\subseteq H$, then
\begin{itemize}
\item[(d)] $[K:H]=[q(K):q(H)]$.
\end{itemize}

\label{logalpha}
Let $G$ be a locally compact group, $\phi:G\to G$ a topological automorphism and $U\in\mathcal B(G)$. For every positive integer $n$ let $c_n:=[U:C_n(\phi,U)]$. Then:
\begin{itemize}
\item[(a)] $c_{n}$ divides $c_{n+1}$ for every $n>0$. 
\end{itemize}
For every $n>0$ let $\alpha_{n}=\frac{c_{n+1}}{c_{n}}=[C_{n}(\phi,U):C_{n+1}(\phi,U)]$. Then:
\begin{itemize}
\item[(b)] $\alpha_{n+1}\leq\alpha_{n}$ for every $n>0$;
\item[(c)] the sequence $\{\alpha_n\}_{n>0}$ stabilizes (i.e., there exist integers $n_0>0$ and $\alpha>0$ such that $\alpha_n=\alpha$ for every $n\geq n_0$);
\item[(d)] $H_{top}(\phi,U)=\log\alpha$.
\end{itemize}

\label{lf+}
Let $G$ be a totally disconnected locally compact group, $\phi:G\to G$ a topological automorphism and $U\in\mathcal B(G)$. Then 
$$H_{top}(\phi,U)=\log[\phi(C(\phi^{-1},U)):C(\phi^{-1},U)].$$

By Lemma \ref{logalpha} there exist integers $n_0>0$ and $\alpha> 0$ such that $\alpha_n=\alpha$ for every $n\geq n_0$, where $\alpha_{n}=[C_{n}(\phi,U):C_{n+1}(\phi,U)]$ for every $n>0$, and $H_{top}(\phi,U)=\log\alpha$. So it suffices to prove that 
\begin{equation}\label{aim}
[\phi(C(\phi^{-1},U)):C(\phi^{-1},U)]=\alpha.
\end{equation}

Since $C(\phi^{-1},U)=U\cap \phi(C(\phi^{-1},U))$, and by Fact \ref{gi}(b), we have
\begin{equation}\label{eqa}\begin{split}
[\phi(C(\phi^{-1},U)):C(\phi^{-1},U)]&=[\phi(C(\phi^{-1},U)):U\cap \phi(C(\phi^{-1},U))]\\&=[\phi(C(\phi,U))\cdot U:U].
\end{split}\end{equation}
The family of cosets $(\phi(U)\cdot U)/U$ is finite, as $U$ is open and $\phi(U)\cdot U$ is compact, since both $U$ and $\phi(U)$ are compact. Consequently, the sequence $\{(\phi(C_n(\phi^{-1},U))\cdot U)/U\}_{n>0}$ is a descending chain of finite subsets of $(\phi(U)\cdot U)/U$ (note that $\phi(C_1(\phi^{-1},U))=\phi(U)$), hence it stabilizes, that is there exists $n_1>0$ such that 
\begin{equation}\label{n1n}
\phi(C_n(\phi^{-1},U))\cdot U=\phi(C_{n_1}(\phi^{-1},U))\cdot U\ \text{for every}\ n\geq n_1;
\end{equation}
in other words, 
\begin{equation}\label{iot}
\bigcap_{n=1}^\infty (\phi(C_{n}(\phi^{-1},U))\cdot U)=\phi(C_{n_1}(\phi^{-1},U))\cdot U.
\end{equation}
Now Lemma \ref{intersect} gives
\begin{equation}\label{lemmagives}
\bigcap_{n=1}^\infty (\phi(C_{n}(\phi^{-1},U))\cdot U)=\left(\bigcap_{n=1}^\infty \phi(C_n(\phi^{-1},U))\right)\cdot U=\phi(C(\phi^{-1},U))\cdot U,
\end{equation}
since $\bigcap_{n=1}^\infty \phi(C_n(\phi^{-1},U))=\phi(C(\phi^{-1},U))$. 
Therefore, \eqref{n1n}, \eqref{iot} and \eqref{lemmagives} yield
\begin{equation}\label{eqb}
\phi(C(\phi^{-1},U))\cdot U=\phi(C_{n_1}(\phi^{-1},U)) \cdot U=\phi(C_{n}(\phi^{-1},U)) \cdot U\ \text{for every}\ n\geq n_1.
\end{equation}
Let $n\geq\max\{n_0,n_1\}$. Then \eqref{eqa} and \eqref{eqb}, together with Fact \ref{gi}(b), give 
\begin{equation}\label{split}\begin{split}
[\phi(C(\phi^{-1},U)):C(\phi^{-1},U)]&=[\phi(C(\phi^{-1},U))\cdot U:U]\\&=[\phi(C_n(\phi^{-1},U))\cdot U:U]\\&=[\phi(C_n(\phi^{-1},U)):\phi(C_n(\phi^{-1},U))\cap U]\\&=[\phi(C_n(\phi^{-1},U)):C_{n+1}(\phi^{-1},U)].
\end{split}\end{equation}
Applying $\phi^{-n}$, we have the equalities 
$$\phi^{-n}(C_{n+1}(\phi^{-1},U))=C_{n+1}(\phi,U)\ \text{and}\ \phi^{-n}(\phi(C_n(\phi^{-1},U)))=C_n(\phi,U),$$ so, since $\phi^{-n}$ is an isomorphism, we have
\begin{equation}\label{lasteq}
[\phi(C_n(\phi^{-1},U)):C_{n+1}(\phi^{-1},U)]=[C_n(\phi,U):C_{n+1}(\phi,U)]=\alpha.
\end{equation}
By \eqref{split} and \eqref{lasteq} we can conclude that \eqref{aim} holds, so the thesis is proved.

