\label{Delta}
Let $G$ be a totally disconnected locally compact group, $\phi:G\to G$ a topological automorphism and $U\in\mathcal B(G)$. Then
\begin{itemize}
\item[(a)]  $\Delta(\phi)=\frac{\mu(\phi(U))}{\mu(U)}=\frac{[\phi(U):U\cap\phi(U)]}{[U:U\cap\phi(U)]}$.
\item[(b)] If $V\in\mathcal B(G)$ and $V\subseteq U\cap \phi(U)$, then $[\phi(U):V]=[U:V]\cdot\Delta(\phi)$.
\end{itemize}

\label{lf-}
Let $G$ be a totally disconnected locally compact group, $\phi:G\to G$ a topological automorphism and $U\in\mathcal B(G)$. Then 
$$H_{top}(\phi,U)=\log[\phi^{-1}(C(\phi,U)):C(\phi,U)]+\log\Delta(\phi).$$

\label{antim}
Let $G$ be a totally disconnected locally compact groupa and $\phi:G\to G$ a continuous endomorphism.
For any $U,V\in\mathcal B(K)$, if $U\subseteq V$, then $H_{top}(\phi,V)\leq H_{top}(\phi,U)$.

Let $\psi=\xi\phi\xi^{-1}$. It is clear that, for $U\in\mathcal B(G)$,
\begin{equation}\label{uff}
\xi(C(\phi,U))=C(\psi,\xi(U)).
\end{equation}

Since $\xi:G\to H$ is a topological isomorphism, it induces a bijection $\mathcal B(G)\to \mathcal B(H)$, so by Theorem \ref{lf+} it suffices to check that 
\begin{equation}\label{suff}
[\phi(C(\phi^{-1},U)):C(\phi^{-1},U)]=[\psi(C(\psi^{-1},\xi(U))):C(\psi^{-1},\xi(U))].
\end{equation}
From \eqref{uff} applied to $\phi^{-1}$ and $\psi^{-1}$ we have $C(\psi^{-1},\xi(U))=\xi(C(\phi^{-1},U))$, so, using also the fact that $\xi$ is an isomorphism,
\begin{equation*}\begin{split}
[\psi(C(\psi^{-1},\xi(U))):C(\psi^{-1},\xi(U))]=[\psi(\xi(C(\phi^{-1},U))):\xi(C(\phi^{-1},U))]=\\
=[\xi(\phi(C(\phi^{-1},U))):\xi(C(\phi^{-1},U))]=[\phi(C(\phi^{-1},U)):C(\phi^{-1},U)];
\end{split}\end{equation*}
then \eqref{suff} is verified and this concludes the proof.

\label{monotonicity}
Let $G$ be a totally disconnected locally compact group, $\phi:G\to G$ a topological automorphism and $N$ a closed normal subgroup of $G$ such that $\phi(N)=N$, and let $\overline\phi:G/N\to G/N$ be the topological automorphism induced by $\phi$. Then:
\begin{itemize}
\item[(a)] $C(\phi\restriction_N,U\cap N)=C(\phi,U)\cap N$ for every $U\in\mathcal B(G)$, and $h_{top}(\phi)\geq h_{top}(\phi\restriction_N)$;
\item[(b)] $C(\overline\phi,q(U))=q(C(\phi,U))$ for every $U\in\mathcal B(G)$ such that $N\subseteq U$, where $q:G\to G/N$ is the canonical projection; moreover, $h_{top}(\phi)\geq h_{top}(\overline\phi)$.
\end{itemize}

(a) The first assertion is clear. Let $V\in \mathcal B(N)$. Then $V= U\cap N$ for some $U\in\mathcal B(G)$. We verify that $$H_{top}(\phi\restriction_N,V)\leq H_{top}(\phi,U)$$ and this implies the wanted inequality.
By the first assertion in item (a), $C((\phi\restriction_N)^{-1},V)=C(\phi^{-1},U)\cap N$, so Fact \ref{gi}(c) gives
\begin{equation*}\begin{split}
[\phi\restriction_N(C((\phi\restriction_N)^{-1},V)):C((\phi\restriction_N)^{-1},V)]&=[\phi(C(\phi^{-1},U)\cap N):C(\phi^{-1},U)\cap N]\\&\leq[\phi(C(\phi^{-1},U)):C(\phi^{-1},U)].
\end{split}\end{equation*}
By Theorem \ref{lf+}, taking the logarithms, this inequality gives $H_{top}(\phi\restriction_N,V)\leq H_{top}(\phi,U)$.

\smallskip
(b) The proof of the first assertion is straightforward. Let $q:G\to G/N$ be the canonical projection and $q(U)\in\mathcal B(G/N)$, where $U\in\mathcal B(G)$; we can assume without loss of generality that $N\subseteq U$. Since $N\subseteq C(\phi^{-1},U)$, by the first assertion in item (b) and Fact \ref{gi}(d) we have 
\begin{equation*}\begin{split}
[\overline\phi(C(\overline\phi^{-1},q(U))):C(\overline\phi^{-1},q(U))]=[\overline\phi(q(C(\phi^{-1},U))):q(C(\phi^{-1},U))]=\\
=[q(\phi(C(\phi^{-1},U))):q(C(\phi^{-1},U))]]=[\phi(C(\phi^{-1},U)):C(\phi^{-1},U)].
\end{split}\end{equation*}
Theorem \ref{lf+} applies to this equality and gives $H_{top}(\overline\phi,q(U))=H_{top}(\phi,U)$, hence we can conclude that $h_{top}(\overline\phi)\leq h_{top}(\phi)$.

By Proposition \ref{monotonicity}(b) the inequality $h_{top}(\phi)\geq\sup_{i\in I}h_{top}(\overline\phi_i)$ holds. So let $U\in\mathcal B(G)$. There exists $i\in I$ such that $N_i\subseteq U$. Let $q_i:G\to G/N_i$ be the canonical projection. Since $N_i\subseteq C(\phi^{-1},U)$, by Proposition \ref{monotonicity}(b) and Fact \ref{gi}(d) we have 
\begin{equation*}\begin{split}
[\overline\phi_i(C(\overline\phi_i^{-1},q_i(U))):C(\overline\phi_i^{-1},q_i(U))]=[\overline\phi_i(q_i(C(\phi^{-1},U))):q_i(C(\phi^{-1},U))]\\
=[q_i(\phi(C(\phi^{-1},U))):q_i(C(\phi^{-1},U))]=[\phi(C(\phi^{-1},U)):C(\phi^{-1},U)].
\end{split}\end{equation*}
Theorem \ref{lf+} applies to this equality and gives $H_{top}(\overline\phi_i,q_i(U))=H_{top}(\phi,U)$. Therefore $H_{top}(\phi,U)\leq h_{top}(\overline\phi_i)$, hence we can conclude that $h_{top}(\phi)\leq\sup_{i\in I}h_{top}(\overline\phi_i)$.
